#[test]
fn adversarial_order3_insert_delete_reverse() {
    let mut tree = BTree::with_order(3);
    for i in 0..100 { tree.insert(i, i); }
    for i in (0..100).rev() {
        tree.delete(&i).unwrap();
        if !tree.verify() {
            panic!("order-3 delete failed at {i}");
        }
    }
    assert!(tree.is_empty());
}

#[test]
fn adversarial_order3_small_reverse_delete() {
    let mut tree = BTree::with_order(3);
    for i in 0..10 { tree.insert(i, i); }
    for i in (0..10).rev() {
        tree.delete(&i).unwrap();
        if let Err(reason) = tree.verify_reason() {
            panic!("order-3 small delete failed at {i}: {reason}");
        }
    }
    assert!(tree.is_empty());
}

